/**
 * -------------------------------------------------------------------
 * File Name: scrolltop.js
 * Description: This file implements a scroll-to-top button with a visual progress indicator
 *              using an SVG path. It uses jQuery for DOM manipulation and animation.
 *
 * Functionality:
 * - Creates a visual progress indicator on a scroll-to-top button using an SVG path's stroke-dashoffset property.
 * - Dynamically updates the stroke-dashoffset based on the user's scroll position on the page.
 * - Adds an "active" class to the scroll-to-top button when the user scrolls down past a certain point (50px).
 * - Implements smooth scrolling to the top of the page when the button is clicked.
 *
 * Dependencies:
 * - jQuery library must be included in the HTML file before this script.
 * -------------------------------------------------------------------
 */
!(function (o) {
    "use strict"; // Enable strict mode for better JavaScript practices
  
    // Execute code when the document is fully loaded and ready
    o(document).ready(function () {
  
      /**
       * t - Updates the stroke-dashoffset of the SVG path to visually represent scroll progress.
       *
       * This function is called on every scroll event. It calculates the scroll progress as a
       * percentage of the total scrollable height and updates the `strokeDashoffset` property
       * of the SVG path, creating a visual filling effect as the user scrolls down.
       *
       * @function t
       * @returns {void}
       */
      function t() {
        // Get the current vertical scroll position from the top of the document
        var t = o(window).scrollTop(),
          // Calculate the total scrollable height of the document
          e = o(document).height() - o(window).height();
        // Update the strokeDashoffset property of the SVG path element (r) to represent scroll progress.
        // The strokeDashoffset is calculated based on the current scroll position (t)
        // relative to the total scrollable height (e) and the total length of the path (n).
        r.style.strokeDashoffset = n - (t * n) / e;
      }
  
      // Select the SVG path element with class 'scroll-to-top path'
      var r = document.querySelector(".scroll-to-top path"),
        // Get the total length of the SVG path. This is used to calculate the stroke-dashoffset.
        n = r.getTotalLength();
  
      // Disable transitions initially to avoid animation on page load
      r.style.transition = r.style.WebkitTransition = "none";
      // Set the strokeDasharray and strokeDashoffset properties to the total length (n).
      // This makes the path initially invisible (hidden behind the dash offset).
      r.style.strokeDasharray = n + " " + n;
      r.style.strokeDashoffset = n;
      // Force a reflow to apply the initial styles without transition
      r.getBoundingClientRect();
      // Enable transition for smooth animation on scroll. Set transition property for stroke-dashoffset.
      r.style.transition = r.style.WebkitTransition = "stroke-dashoffset 10ms linear";
  
      // Call the 't' function immediately to set the initial state of the progress indicator
      t();
      // Attach the 't' function to the window's scroll event.
      // This ensures that the 't' function is executed every time the user scrolls,
      // updating the progress indicator dynamically.
      o(window).scroll(t);
  
      // --- Scroll-to-top button activation and smooth scrolling ---
  
      // jQuery event listener for the window scroll event
      jQuery(window).on("scroll", function () {
        // Check if the vertical scroll position from the top is greater than 50 pixels
        if (50 < jQuery(this).scrollTop()) {
          // If scrolled more than 50px, add the class 'scroll-top-active' to the element with class 'scroll-to-top'.
          // This class likely controls the visibility or appearance of the scroll-to-top button.
          jQuery(".scroll-to-top").addClass("scroll-top-active");
        } else {
          // If scrolled less than or equal to 50px, remove the class 'scroll-top-active'
          jQuery(".scroll-to-top").removeClass("scroll-top-active");
        }
      }),
  
      // jQuery event listener for the click event on the element with class 'scroll-to-top'
      jQuery(".scroll-to-top").on("click", function (t) {
        // Prevent the default action of the event (e.g., following a link if the button is an anchor tag)
        t.preventDefault();
        // Animate the scroll to the top of the page.
        // 'html, body' ensures it works across browsers.
        // 'scrollTop: 0' sets the vertical scroll position to 0 (top of the page).
        // '550' is the duration of the animation in milliseconds (0.55 seconds).
        jQuery("html, body").animate({ scrollTop: 0 }, 550);
        // Return false to explicitly prevent further event propagation (though preventDefault should suffice here)
        return false;
      })
    })
  })(jQuery);